export function chaewonLocation(s){const pin=personalEventPosition(s,'chaewon');if(pin)return pin;const m=s.clock.minute;return m>=960&&m<1020?'gym':m>=1020&&m<1080?'hall':m>=1080&&m<1140?'cafeteria':null;}
function chaewonCompanionHere(s,id,place){if(!characterPresent(s,id))return false;if(id==='iseo')return (personalEventPosition(s,id)??iseoEventLocation(s))===place;return presentPeople(s,place).includes(id);}
function chaewonHasTime(s,ids,minutes){return !(s.appointments??[]).some(a=>a.status==='pending'&&a.day===s.day&&a.minute>=s.clock.minute&&a.minute<s.clock.minute+minutes);}
export function chaewonEventsAt(s,place=s.location){
 if(s.academics?.registrationPending||s.freeDay?.home||(s.world?.stage??'campus')!=='campus'||!characterPresent(s,'chaewon')||chaewonLocation(s)!==place)return [];
 return Object.entries(chaewonStories).filter(([id,d])=>{const r=s.personalEvents?.records?.[id],prior=s.personalEvents?.records?.[d.previous];if(r?.status==='completed'||!d.places.includes(place)||!chaewonHasTime(s,['chaewon',d.partner].filter(Boolean),r?.stage?20:30))return false;if(d.previous&&(prior?.status!=='completed'||s.day<=prior.completedDay||!contact(s,'chaewon').introduced))return false;
 if(d.partner){if(relationship(s,'chaewon').tension>=4||relationship(s,'chaewon').trust<1||relationship(s,'chaewon',d.partner).tension>=4||relationship(s,d.partner,'chaewon').tension>=4)return false;const bond=relationship(s,d.partner);if(!contact(s,d.partner).introduced||bond.familiarity<3||bond.trust<2||bond.tension>=4||!chaewonCompanionHere(s,d.partner,place))return false;}return true;}).map(([eventId,d])=>({eventId,person:'chaewon',title:contact(s,'chaewon').introduced?d.title:'기구 옆에서 기다리는 학생',resuming:s.personalEvents?.records?.[eventId]?.status==='paused'}));
}
export function beginChaewonEvent(state,id){if(!chaewonEventsAt(state).some(e=>e.eventId===id))throw new Error('같은 장소에서 만날 수 있는지 다시 확인해 주세요.');const s=structuredClone(state);s.personalEvents??={active:null,records:{}};const store=s.personalEvents,old=store.records[id],prior=store.records[store.active],d=chaewonStories[id];if(prior?.status==='active')prior.status='paused';store.records[id]={...old,eventId:id,person:'chaewon',participants:['chaewon',...(d.partner?[d.partner]:[])],episode:d.episode,status:'active',stage:old?.stage??0,choices:old?.choices??[],day:s.day,location:s.location,until:s.clock.minute+(old?.stage?20:30)};store.active=id;seePeople(s,store.records[id].participants);return s;}
export function chaewonEventView(s){const r=s.personalEvents.records[s.personalEvents.active],d=chaewonStories[r.eventId];return {...d,...r,title:contact(s,'chaewon').introduced?d.title:'기구 옆에서 기다리는 학생',opening:d.opening.replace(/^채원: /,''),options:r.status==='completed'?[]:(r.stage?d.second.filter(o=>o[0]!=='names'||!contact(s,'chaewon').introduced):d.options).map(o=>o.slice(0,2))};}
export function progressChaewonEvent(state,choice){const r=state.personalEvents.records[state.personalEvents.active],d=chaewonStories[r.eventId],option=(r.stage?d.second:d.options).find(o=>o[0]===choice),minutes=r.stage?20:10;if(!option||!chaewonEventView(state).options.some(o=>o[0]===choice)||r.status!=='active'||r.day!==state.day||r.location!==state.location||state.clock.minute+minutes>r.until||!characterPresent(state,'chaewon')||!chaewonHasTime(state,r.participants,minutes)||d.partner&&!chaewonCompanionHere(state,d.partner,state.location))throw new Error('지금 함께 있는 사람과 시간을 다시 확인해 주세요.');
 const s=advanceFreeTime(state,minutes),rec=s.personalEvents.records[r.eventId];rec.choices.push(choice);if(choice==='names'){introduce(s,'chaewon','gym-introduction');s.contacts.chaewon.details={age:21,major:'대학교 재학 중'};}seePeople(s,rec.participants);rec.last={player:option[1],text:option[2]};
 if(d.partner){const partnerLine=d.partner==='iseo'?(choice==='share'?'그럼 저는 매트요. 아, 정리 끝나면 또 운동하자고 안 할게요.':choice==='rest'?'찬성이요. 앉아서 물 마시는 것도 오늘 할 일에 넣어요.':'오늘 할 만큼 했죠. 다음에는 시작하기 전에 끝낼 시간부터 정해요.'):(choice==='walk'?'저도 잠깐 괜찮아요. 대신 제 일정은 제가 확인하고 갈게요.':choice==='stay'?'저는 하고 싶은 걸 먼저 적어놔요. 부탁받기 전에 제 시간을 알아야 하니까요.':'자기 시간 지키는 게 미안한 일은 아니잖아요. 다음에 또 봐요.');rec.last.lines=[{person:d.partner,text:partnerLine},{person:'chaewon',text:option[2]}];if(choice==='walk'&&wetWeather(s)){rec.last.text='비가 오네요. 밖에 걷는 건 다음에 하고, 처마 안쪽에서 잠깐 쉬어요.';rec.last.lines.at(-1).text=rec.last.text;}}
 changeRelationship(s,'chaewon','taei',{familiarity:1,trust:choice==='names'?1:0});
 if(r.stage){rec.status='completed';rec.completedDay=s.day;rec.completedMinute=s.clock.minute;rec.result=d.title+' · '+option[1];if(d.partner){changeRelationship(s,'chaewon',d.partner,{familiarity:1,trust:1});changeRelationship(s,d.partner,'chaewon',{familiarity:1,trust:1});}s.lastResult=rec.result;s.memory.push(`[${s.day}일차] ${displayName(s,'chaewon')} · ${rec.result}`);if(!s.known.includes(d.title+' 기록'))s.known.push(d.title+' 기록');}else rec.stage=1;s.pace={count:0,seen:{}};return s;
}
